// A catalogue translates independently of its preserved View snapshots.
export async function translateCatalogue(views, target, request, { signal, cache = {}, wait = delay } = {}) {
  const records = [...new Map(views.filter(view => /^[A-Za-z0-9_-]{12,40}$/.test(view.id)).map(view => [view.id, view])).values()].sort((a, b) => a.id.localeCompare(b.id));
  const missing = records.filter(view => !cache[view.id]);
  const translated = { ...cache };
  for (let start = 0; start < missing.length; start += 20) {
    const ids = missing.slice(start, start + 20).map(view => view.id);
    let result;
    for (let attempt = 0; attempt < 8; attempt++) {
      signal?.throwIfAborted();
      result = await request(ids, target, signal);
      signal?.throwIfAborted();
      if (result.status !== 'preparing') break;
      await wait(Math.min(2000 + attempt * 1000, 6000), signal);
    }
    if (!result?.translations) throw new Error('translation_unavailable');
    Object.assign(translated, result.translations);
  }
  return translated;
}
function delay(ms, signal) {
  return new Promise((resolve, reject) => {
    const done = () => { signal?.removeEventListener('abort', abort); resolve(); };
    const timer = setTimeout(done, ms);
    const abort = () => { clearTimeout(timer); reject(signal.reason); };
    if (signal?.aborted) abort();
    else signal?.addEventListener('abort', abort, { once: true });
  });
}
